import * as React from "react"
import {
  AlertCircle,
  CheckCircle2,
  CircleX,
  Info,
  SquareDashed,
} from "lucide-react"
import { cva, type VariantProps } from "class-variance-authority"

import { cn } from "@/lib/utils"

const alertVariants = cva(
  "flex w-full flex-col items-end gap-3 rounded-[8px] border bg-white px-3 py-3 text-[14px] leading-[20px] shadow-[0px_2px_4px_-2px_rgba(19,25,39,0.12),0px_4px_4px_-2px_rgba(19,25,39,0.08)]",
  {
    variants: {
      variant: {
        default: "border-[#e6e6e6] text-black",
        success: "border-[#307f4a] text-[#307f4a]",
        error: "border-[#e73f3f] text-[#e73f3f]",
        destructive: "border-[#e73f3f] text-[#e73f3f]",
        warning: "border-[#e49614] text-[#e49614]",
        info: "border-[#2563eb] text-[#2563eb]",
      },
    },
    defaultVariants: {
      variant: "default",
    },
  }
)

const alertIconVariants = cva("flex h-6 w-6 shrink-0 items-center justify-center", {
  variants: {
    variant: {
      default: "text-[#adacb0]",
      success: "text-[#307f4a]",
      error: "text-[#e73f3f]",
      destructive: "text-[#e73f3f]",
      warning: "text-[#e49614]",
      info: "text-[#2563eb]",
    },
  },
  defaultVariants: {
    variant: "default",
  },
})

type AlertVariant = NonNullable<VariantProps<typeof alertVariants>["variant"]>
type AlertState = "warning" | "neutral" | "success" | "negative"

const stateToVariant: Record<AlertState, AlertVariant> = {
  warning: "warning",
  neutral: "default",
  success: "success",
  negative: "error",
}

const Alert = React.forwardRef<
  HTMLDivElement,
  React.HTMLAttributes<HTMLDivElement> &
    VariantProps<typeof alertVariants> & {
      icon?: React.ReactNode
      showIcon?: boolean
      state?: AlertState
      action?: React.ReactNode
    }
>(({ className, variant, icon, showIcon = true, state, action, children, ...props }, ref) => {
  const resolvedVariant = (state ? stateToVariant[state] : variant ?? "default") as AlertVariant
  const defaultIcons: Record<AlertVariant, React.ReactNode> = {
    default: <SquareDashed className="h-5 w-5" />,
    success: <CheckCircle2 className="h-5 w-5" />,
    error: <CircleX className="h-5 w-5" />,
    destructive: <CircleX className="h-5 w-5" />,
    warning: <AlertCircle className="h-5 w-5" />,
    info: <Info className="h-5 w-5" />,
  }
  const resolvedIcon = icon === undefined ? defaultIcons[resolvedVariant] : icon

  return (
    <div
      ref={ref}
      role="alert"
      className={cn(alertVariants({ variant: resolvedVariant }), className)}
      {...props}
    >
      <div className="flex w-full items-start gap-2">
        {showIcon && resolvedIcon ? (
          <span className={cn(alertIconVariants({ variant: resolvedVariant }))}>
            {resolvedIcon}
          </span>
        ) : null}
        <div className="min-w-0 flex-1">{children}</div>
      </div>
      {action ? <div className="flex w-full justify-end">{action}</div> : null}
    </div>
  )
})
Alert.displayName = "Alert"

const AlertTitle = React.forwardRef<
  HTMLParagraphElement,
  React.HTMLAttributes<HTMLHeadingElement>
>(({ className, ...props }, ref) => (
  <h5
    ref={ref}
    className={cn("text-[14px] font-normal leading-[20px] text-current", className)}
    {...props}
  />
))
AlertTitle.displayName = "AlertTitle"

const AlertDescription = React.forwardRef<
  HTMLParagraphElement,
  React.HTMLAttributes<HTMLParagraphElement>
>(({ className, ...props }, ref) => (
  <div
    ref={ref}
    className={cn(
      "text-[12px] leading-[16px] text-[#7f7d83] [&:not(:first-child)]:mt-2",
      className
    )}
    {...props}
  />
))
AlertDescription.displayName = "AlertDescription"

export { Alert, AlertTitle, AlertDescription }
